L["Also a grey ! for quests you can still pick up that no longer give experience."] = "Anche un ! grigio per le missioni che puoi ancora prendere ma che non danno più esperienza."
L["Also a grey star on the map for the rares you have killed."] = "Anche una stella grigia sulla mappa per i rari che hai ucciso."
