L["Also in use on"] = "In uso anche su"
L["Also keeps your last whispers and group chat lines with each player."] = "Tiene anche gli ultimi sussurri e le righe della chat di gruppo con ogni giocatore."
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "Apre anche la mappa del mondo sul punto di riferimento, così vedi dov'è. Solo fuori dal combattimento."
L["Also prints the summary when you leave a raid."] = "Stampa il riepilogo anche quando lasci un'incursione."
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "Ti avvisa anche dentro le istanze. Disattivato in modo predefinito: poche hanno erbe o minerali."
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "Mostra anche il profitto di ogni ricetta a destra della sua riga nella lista, in verde o rosso. Le ricette di cui non si conosce il profitto non ne mostrano."
L["Also thanks players in your party or raid."] = "Ringrazia anche i giocatori nel tuo gruppo o incursione."
L["Also used inside dungeons and raids."] = "Usato anche dentro spedizioni e incursioni."
L["Also warns about rares you have killed before."] = "Avvisa anche per i rari che hai già ucciso."
L["Also warns while your pet is set to passive."] = "Avvisa anche mentre il tuo famiglio è impostato su passivo."
L["Also warns while your pet's health is under the threshold, in combat too."] = "Avvisa anche mentre la salute del tuo famiglio è sotto la soglia, anche in combattimento."
L["Also worth a look"] = "Vale anche la pena di vedere"
