L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest in this profile; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "Alt-clic su una ricompensa a scelta, nel registro missioni o dall'assegnatore, per salvarla per quella missione in questo profilo; Alt-clic di nuovo per annullarla. Viene selezionata quando consegni la missione, e Consegna missioni la prende per te."
L["Alt-click an item in your bags to mark it as scrap, and sell it at the next vendor."] = "Alt-clic su un oggetto nelle borse per segnarlo come scarto e venderlo al prossimo mercante."
L["Alts Button on Mail"] = "Pulsante alt nella posta"
