L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "Un errore \"L'inventario è pieno\" fa comparire la riga per 20 secondi, anche con più spazi liberi della soglia qui sopra."
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "Un alt che ha già questa macro, per nome e testo o solo testo, usa la propria."
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "Un pulsante Alt accanto alla scheda Invia della cassetta postale elenca i tuoi personaggi su questo reame e fazione con livello e oro. Scegline uno per compilare il campo A."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "Un pulsante Allega accanto alla scheda Invia della cassetta postale: allega ogni bene commerciale, un tipo di bene commerciale o il tuo equipaggiamento non vincolato con un clic."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "Un ID che il gioco tiene nascosto: Nascondi riga lo omette dal tooltip, Mostra nascosti mostra la riga con Nascosto al posto del numero."
L["An item worth more at the auction house than at a vendor is valued at its auction price, from your last Scan Prices or TradeSkillMaster."] = "Un oggetto che vale di più alla casa d'aste che da un mercante viene valutato al prezzo d'asta, dalla tua ultima Scansiona prezzi o da TradeSkillMaster."
L["An on-next-swing attack queued on the melee bars."] = "Un attacco al prossimo colpo in coda sulle barre del corpo a corpo."
