L["Buys on the auction house the materials for that many crafts, whatever is already in your bags: every checked reagent that vendors do not sell. Set the number with the - and + beside it; uncheck a reagent to leave it out. Each material asks for the price now and waits for you to confirm."] = "Compra alla casa d'aste i materiali per quel numero di creazioni, indipendentemente da ciò che hai già nelle borse: ogni reagente spuntato che i mercanti non vendono. Imposta il numero con - e + accanto; togli la spunta a un reagente per escluderlo. Ogni materiale chiede il prezzo attuale e aspetta la tua conferma."
L["Buys what your bags lack of this merchant's reagents for %d crafts, the orange number next to the recipe, so Create All can make them all. Uncheck a reagent to leave it out."] = "Compra ciò che manca nelle borse dei reagenti di questo mercante per %d creazioni, il numero arancione accanto alla ricetta, così Crea tutto può crearle tutte. Togli la spunta a un reagente per escluderlo."
