L["Every paladin in your group running Naowh Forever, and the blessing they give each class. Click an icon to change it: your own row always, anyone's while you lead the group or are an assistant. Only what that paladin has learned is offered, and changes reach them straight away."] = "Ogni paladino nel tuo gruppo che usa Naowh Forever, e la benedizione che dà a ogni classe. Clicca un'icona per cambiarla: sempre la tua riga, quella di chiunque se sei il capogruppo o un assistente. Viene offerto solo ciò che quel paladino ha appreso, e le modifiche gli arrivano subito."
