L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "Per i paladini, un pulsante per ogni classe nel tuo gruppo. Il clic sinistro benedice il prossimo membro di quella classe che ne ha bisogno, prima chi non l'ha, saltando chi è morto o fuori portata. Clic destro su una classe per scegliere la sua benedizione o aprire la lista dei giocatori. Spostalo nell'Editor HUD. L'anteprima lo modifica: clic destro su una classe per la sua benedizione, clicca l'aura per sceglierla, rotellina per la dimensione e Maiusc-rotellina per la spaziatura, trascina lo spazio dopo l'aura, x nasconde un pulsante e + lo riporta."
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Per i personaggi Skyborne: linee di energia (Alleanza, per Read Ley Line) o Convergenze elementali (Orda, per Skysight) segnate sulla mappa del mondo. Il gioco non le segna: l'addon conosce quelle trovate dai giocatori e salva ogni nuova su cui lanci la tua abilità razziale. Le altre razze non vedono segnalini."
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "Per la tua classe: importa questo set una volta su un nuovo personaggio, al livello 1 senza ancora esperienza."
L["For your level"] = "Per il tuo livello"
L["Forget %s on %s? It comes back the next time you log in on it with a Mail & Alts option on."] = "Dimenticare %s su %s? Tornerà al prossimo accesso con quel personaggio con un'opzione di Posta e alt attiva."
