L["Hover a badged name in chat to see their card."] = "Passa sopra un nome con distintivo in chat per vedere la sua scheda."
L["Hover a spell, item or NPC and press the shortcut to copy its ID. With Tooltips on it opens the copy card; with only Copy Command on, a box with the ID."] = "Passa sopra un incantesimo, oggetto o PNG e premi la scorciatoia per copiarne l'ID. Con Tooltip attivo apre la scheda di copia; con solo Comando di copia attivo, un riquadro con l'ID."
