L["Once Per Player Every"] = "Una volta per giocatore ogni"
L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "Dopo aver scansionato la casa d'aste (Scansiona prezzi), la ricetta scelta mostra quanto costa comprare i reagenti e a quanto si vende l'oggetto, e il profitto dopo la commissione del 5% della casa d'aste. Ogni reagente viene valutato al prezzo più basso: quello di un mercante dopo che l'hai visto venderlo, altrimenti il prezzo d'acquisto immediato più basso alla tua ultima scansione. Deseleziona un reagente che hai già per escluderlo dal costo, per ogni ricetta che lo usa. Passa sopra le righe per il dettaglio."
L["One addon"] = "Un addon"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "Una barra per arma, sincronizzata con l'evento di colpo del gioco, quindi accelerazione da parata, azzeramenti del colpo e celerità sono sempre corretti. Spostale nell'Editor HUD."
L["One Fewer"] = "Uno in meno"
L["One item per click: the game needs a click for every disenchant."] = "Un oggetto per clic: il gioco richiede un clic per ogni disincanto."
L["One More"] = "Uno in più"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "Un numero per l'equipaggiamento di un personaggio, sulla scala del livello oggetto: 26,4 significa equipaggiamento che vale un set di epici di livello 26. Il tuo è sempre sul manichino della lista BiS."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "Un sussurro per riga, scelto a caso; {buff} e {name} vengono compilati."
