L["Only quest chains: the first quest of each one, and the next step of those you are on."] = "Solo catene di missioni: la prima missione di ciascuna, e il passo successivo di quelle che stai facendo."
L["Only the gear that beats what you wear: a higher pick on your BiS list, or a higher item level you can wear."] = "Solo l'equipaggiamento migliore di ciò che indossi: una scelta più alta nella tua lista BiS, o un livello oggetto più alto che puoi indossare."
L["Only the group leader can disband the group."] = "Solo il capogruppo può sciogliere il gruppo."
L["Only the group leader or an assistant can plan every paladin's blessings."] = "Solo il capogruppo o un assistente può pianificare le benedizioni di ogni paladino."
L["Only the loot you still need from your BiS list: higher on it than what you wear, and not in your bags or bank."] = "Solo il bottino che ti serve ancora dalla tua lista BiS: più in alto di ciò che indossi, e non nelle borse né in banca."
L["Only the loot your class can use. Off, the rest is listed faded."] = "Solo il bottino che la tua classe può usare. Se disattivato, il resto è elencato attenuato."
L["Only the macros on your kept slots come along."] = "Vengono incluse solo le macro sui tuoi spazi tenuti."
L["Only the recipes for the professions you have. Off, every recipe is listed."] = "Solo le ricette delle professioni che hai. Se disattivato, vengono elencate tutte le ricette."
