L["What it shows as you leave combat."] = "Cosa mostra quando esci dal combattimento."
L["What Lines Show"] = "Cosa mostrano le righe"
L["What Naowh's profession window adds to each recipe: the ones you have not learned yet, your next rank, and how many of each reagent you have."] = "Cosa aggiunge la finestra delle professioni di Naowh a ogni ricetta: quelle che non hai ancora appreso, il tuo prossimo grado e quanti ne hai di ogni reagente."
L["What opens when a flight starts; Off hides the Games button."] = "Cosa si apre quando inizia un volo; Disattivato nasconde il pulsante Giochi."
L["What Rows Show"] = "Cosa mostrano le righe"
L["What shows while you know a find but track none."] = "Cosa appare quando conosci una ricerca ma non ne tracci nessuna."
L["What the copy card has selected when it opens."] = "Cosa ha selezionato la scheda di copia quando si apre."
L["What the Journal lists on a boss. The same switches as the Filters icon on its title bar."] = "Cosa elenca il Diario su un boss. Gli stessi interruttori dell'icona Filtri sulla sua barra del titolo."
L["What the stack fetches at the auction house, from your last Scan Prices or TradeSkillMaster."] = "Quanto vale la pila alla casa d'aste, dalla tua ultima Scansiona prezzi o da TradeSkillMaster."
L["What the whole stack sells for at a vendor, and each item's price."] = "Quanto vale l'intera pila da un mercante, e il prezzo di ogni oggetto."
L["What to train at each level, and its cost."] = "Cosa apprendere a ogni livello, e il suo costo."
L["What you can train now and what each level brings."] = "Cosa puoi apprendere ora e cosa porta ogni livello."
L["What you can train now, what each level brings and what it costs."] = "Cosa puoi apprendere ora, cosa porta ogni livello e quanto costa."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "Quanto paghi l'artigiano per questa creazione, inviato con il sussurro. Compilato con la mancia consigliata; scrivi la tua come 2g 50s, 75s o 2.5 (oro). Svuotalo per tornare al suggerimento."
L["What you wear that takes a better enchant for your level."] = "Ciò che indossi che accetta un incantamento migliore per il tuo livello."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "Cosa sta facendo il tuo bersaglio in uno scontro: i suoi benefici brevi e gli effetti di controllo su di lui."
L["Wheel"] = "Rotellina"
L["Wheel on the rows"] = "Rotellina sulle righe"
L["Wheel: size. Right-click for more."] = "Rotellina: dimensione. Clic destro per altro."
L["Wheel: text size. Click a line to hide it. Right-click for more."] = "Rotellina: dimensione testo. Clicca una riga per nasconderla. Clic destro per altro."
L["When"] = "Quando"
L["When a profession's skill is high enough for its next rank (Journeyman, Expert, Artisan), a banner under the skill bar and on its card in the overview says what it takes and who teaches it: the nearest trainer, book vendor or quest giver. Click Waypoint to mark them on your map. Reaching it also says so once in chat; /naowh profrank repeats that."] = "Quando l'abilità di una professione è abbastanza alta per il grado successivo (Garzone, Esperto, Artigiano), un banner sotto la barra dell'abilità e sulla sua scheda nella panoramica dice cosa serve e chi lo insegna: l'istruttore più vicino, il venditore di libri o l'assegnatore della missione. Clicca Punto di riferimento per segnarli sulla mappa. Raggiungerlo lo dice anche una volta in chat; /naowh profrank lo ripete."
L["When an item on your list is up for a roll or in the loot window, and again when it is yours. Move the on-screen alert in the HUD Editor."] = "Quando un oggetto della tua lista è in palio o nella finestra del bottino, e di nuovo quando è tuo. Sposta l'avviso sullo schermo nell'Editor HUD."
L["When an NPC offers several things, goes straight to a finished quest to hand in, or the first quest on offer. Works with the two options above."] = "Quando un PNG offre più cose, va dritto a una missione completata da consegnare, o alla prima missione offerta. Funziona con le due opzioni qui sopra."
L["When it is up for a roll or drops."] = "Quando è in palio o viene rilasciato."
L["When it is yours."] = "Quando è tuo."
L["When You Leave"] = "Quando esci"
L["When you level up with new spells to train, a toast says how many and what they cost, with buttons to open the planner and to put a waypoint on your nearest trainer. Move it in the HUD Editor."] = "Quando sali di livello con nuovi incantesimi da apprendere, una notifica dice quanti sono e quanto costano, con pulsanti per aprire il pianificatore e mettere un punto di riferimento sull'istruttore più vicino. Spostala nell'Editor HUD."
L["When you log out, the set this character saved last is saved again with your bars, macros and keybinds as they are."] = "Quando ti disconnetti, il set salvato per ultimo da questo personaggio viene salvato di nuovo con barre, macro e tasti rapidi così come sono."
L["When you reach a city or inn, a flashing list in the middle of the screen of what you are short on. It stays up until you have what you need or leave. Move it in the HUD Editor."] = "Quando raggiungi una città o una locanda, una lista lampeggiante al centro dello schermo di ciò che ti manca. Resta finché non hai ciò che serve o te ne vai. Spostala nell'Editor HUD."
L["When You Reset"] = "Quando azzeri"
L["Where"] = "Dove"
L["Where %s starts is not known."] = "Non si sa dove inizia %s."
L["Where do you want to start?"] = "Da dove vuoi iniziare?"
L["Where it comes from is not recorded yet; try the Auction House."] = "La provenienza non è ancora registrata; prova la Casa d'aste."
L["Where It Drops"] = "Dove viene rilasciato"
L["Where on the frame the bar sits."] = "Dove si trova la barra sul riquadro."
L["Where to get them"] = "Dove ottenerli"
L["Where your distance to pulling aggro and the entry count sit: under the bars, or between the title bar and the bars."] = "Dove stanno la distanza dall'aggro e il conteggio delle voci: sotto le barre, o tra la barra del titolo e le barre."
L["Where your star sits: on the icon's corner, before the name, or hidden."] = "Dove si trova la tua stella: nell'angolo dell'icona, prima del nome, o nascosta."
L["Where? on Whispers"] = "Dove? nei sussurri"
L["Whether a healthstone or a potion comes first."] = "Se viene prima una pietra della salute o una pozione."
L["Whether a new mark counts on every character or only this one."] = "Se un nuovo segno vale per ogni personaggio o solo per questo."
L["Whether NF Food leaves drinks to NF Drink."] = "Se NF Food lascia le bevande a NF Drink."
L["Which blessing you give this class: Might, Wisdom, Kings, Salvation or Light."] = "Quale benedizione dai a questa classe: Potenza, Saggezza, dei Re, Salvezza o Luce."
L["Which crowd control shows, by ability: every rank, and the same spell from items and creatures."] = "Quali effetti di controllo appaiono, per abilità: ogni grado, e lo stesso incantesimo da oggetti e creature."
L["Which debuffs show beside crowd control: off until you light them."] = "Quali penalità appaiono accanto agli effetti di controllo: disattivate finché non le illumini."
L["Which guild and title lines show with players' names, saved by the game itself."] = "Quali righe di gilda e titolo appaiono con i nomi dei giocatori, salvate dal gioco stesso."
L["Which kinds of consumable Scan Bags adds and Ask to Add asks about."] = "Quali tipi di consumabile aggiunge Scansiona borse e per quali chiede Chiedi di aggiungere."
L["Which mana spells get the line."] = "Quali incantesimi a mana ricevono la riga."
L["Which modules do you want?"] = "Quali moduli vuoi?"
L["Which of your picks alert: your BiS only, your top two, or every pick on your list."] = "Quali delle tue scelte avvisano: solo il tuo BiS, le prime due, o ogni scelta della lista."
L["Which the macro uses first when you carry both: a healthstone or a healing potion."] = "Cosa usa prima la macro quando porti entrambi: una pietra della salute o una pozione di cura."
L["While a merchant is open, a Buy button under the chosen recipe's reagents buys from them, in one click, every checked reagent they sell, such as Coarse Thread or Weak Flux, for as many crafts as you set beside it. The total cost shows beside the button; hover Buy for each reagent."] = "Mentre un mercante è aperto, un pulsante Compra sotto i reagenti della ricetta scelta compra da lui, con un clic, ogni reagente spuntato che vende, come Filo grezzo o Fondente debole, per tutte le creazioni che imposti accanto. Il costo totale appare accanto al pulsante; passa sopra Compra per ogni reagente."
L["While flying"] = "In volo"
L["While flying and at the campfire"] = "In volo e al fuoco da campo"
L["While Heroic Strike, Cleave, Maul or Raptor Strike is queued, the melee bars take its color and name."] = "Mentre Assalto Eroico, Fendente, Sbranare o Assalto del Rapace è in coda, le barre del corpo a corpo prendono il suo colore e nome."
L["While the auction house is open, a Buy button under the chosen recipe's reagents buys the materials for as many crafts as you set beside it: every checked reagent that vendors do not sell. Each one shows its price first and is only bought when you click Confirm."] = "Mentre la casa d'aste è aperta, un pulsante Compra sotto i reagenti della ricetta scelta compra i materiali per tutte le creazioni che imposti accanto: ogni reagente spuntato che i mercanti non vendono. Ognuno mostra prima il suo prezzo e viene comprato solo quando clicchi Conferma."
L["While the auction house is open, a Search AH button next to the chosen recipe's name searches it for the item the recipe makes. Unlearned recipes also get Search Recipe, for the pattern, plans or manual that teaches it. Recipes that make no item, such as enchants, get no Search AH."] = "Mentre la casa d'aste è aperta, un pulsante Cerca in CdA accanto al nome della ricetta scelta cerca l'oggetto che crea. Le ricette non apprese hanno anche Cerca ricetta, per lo schema, il progetto o il manuale che la insegna. Le ricette che non creano oggetti, come gli incantamenti, non hanno Cerca in CdA."
L["While the auction house is open, Shift-click a recipe or a reagent to search the auction house for the item: what the recipe makes, or the reagent. While you type in chat, Shift-click still links it."] = "Mentre la casa d'aste è aperta, Maiusc-clic su una ricetta o un reagente per cercare l'oggetto alla casa d'aste: ciò che crea la ricetta, o il reagente. Mentre scrivi in chat, Maiusc-clic lo linka comunque."
L["While the mouse is away, with Show On Mouseover on."] = "Mentre il mouse è lontano, con Mostra al passaggio del mouse attivo."
L["While you are in a group, shares each quest you accept from an NPC with the others, if the quest can be shared. A quest someone shared with you is not shared again. The Modifier as you accept keeps it to yourself."] = "Mentre sei in un gruppo, condivide con gli altri ogni missione che accetti da un PNG, se la missione si può condividere. Una missione che qualcuno ha condiviso con te non viene ricondivisa. Il modificatore all'accettazione la tiene per te."
L["While you carry books, a pin on who takes them: your librarian, or the mage trainer."] = "Mentre porti libri, un segnalino su chi li accetta: il tuo bibliotecario o l'istruttore dei maghi."
L["While you cast, mark where the cast ends on the Main Hand bar. It turns red when the cast will still be going as the swing comes due."] = "Mentre lanci, segna dove finisce il lancio sulla barra della mano primaria. Diventa rosso quando il lancio sarà ancora in corso al momento del colpo."
L["whisper"] = "sussurro"
L["Whisper "] = "Sussurra a "
L["Whisper Lines"] = "Righe di sussurro"
L["Whisper your target"] = "Sussurra al tuo bersaglio"
L["Whispers for "] = "Sussurri per "
L["Whispers thanks when a player gives you a class buff in the open world; turn friendly nameplates on so the game can name them."] = "Sussurra un ringraziamento quando un giocatore ti dà un beneficio di classe nel mondo aperto; attiva le barre dei nomi amichevoli così il gioco può nominarlo."
L["White: exact, from their Naowh Forever. Grey: added up from their gear."] = "Bianco: esatto, dal loro Naowh Forever. Grigio: calcolato dal loro equipaggiamento."
L["Who the cast is aimed at, in their class color."] = "A chi è diretto il lancio, nel suo colore di classe."
L["Whoever holds aggro in one color."] = "Chi ha l'aggro in un solo colore."
L["Whose ranking the picker shows. Each spec keeps its own picks on a list."] = "Di chi è la classifica mostrata dal selettore. Ogni specializzazione tiene le proprie scelte in una lista."
L["Wide kite"] = "Aquilone largo"
L["Widen the swing and Auto Shot windows by your world latency, so they show when to press rather than when the server acts."] = "Allarga le finestre dei colpi e del Tiro automatico della tua latenza del mondo, così mostrano quando premere e non quando agisce il server."
L["Width"] = "Larghezza"
L["Width and Height"] = "Larghezza e altezza"
L["Wild Lines"] = "Righe del Selvaggio"
L["Window"] = "Finestra"
L["Window Color"] = "Colore finestra"
L["Window Height"] = "Altezza finestra"
L["Window Length"] = "Lunghezza finestra"
L["Window Lock"] = "Blocco finestra"
L["Window Opacity"] = "Opacità finestra"
L["Window opacity"] = "Opacità finestra"
L["Window Scale"] = "Scala finestra"
L["Windows cannot be opened or closed by a command in combat."] = "Le finestre non si possono aprire o chiudere con un comando in combattimento."
L["Windows cannot be opened or closed by a command with a gamepad."] = "Le finestre non si possono aprire o chiudere con un comando con un gamepad."
L["With Enchanting open, a Disenchant button at the top of the window opens a window of every item in your bags you can disenchant: green, blue and purple weapons and armor (or type /naowh disenchant). Right-click an item to keep it: it is never disenchanted, on any character, until you right-click it again. Disenchant All disenchants the rest one by one, one item per click, as the game asks a click for every disenchant. An item the game will not take (skill too low) is skipped until you reload. Closes when combat starts."] = "Con Incantamento aperto, un pulsante Disincanta in cima alla finestra apre una finestra con ogni oggetto nelle borse che puoi disincantare: armi e armature verdi, blu e viola (o digita /naowh disenchant). Clic destro su un oggetto per tenerlo: non viene mai disincantato, su nessun personaggio, finché non lo riclicchi con il destro. Disincanta tutto disincanta il resto uno per uno, un oggetto per clic, dato che il gioco richiede un clic per ogni disincanto. Un oggetto che il gioco non accetta (abilità troppo bassa) viene saltato fino al prossimo reload. Si chiude quando inizia il combattimento."
L["With rested experience ahead of the fill."] = "Con l'esperienza da riposo oltre il riempimento."
L["With their badge"] = "Con il loro distintivo"
L["With their badge and Naowh Score"] = "Con il loro distintivo e Naowh Score"
L["With their Naowh Score"] = "Con il loro Naowh Score"
