L["Your bar in a darker shade of your theme's Accent instead of the color picked above. The tank and aggro line colors stay as picked."] = "La tua barra in una tonalità più scura dell'accento del tuo tema invece del colore scelto sopra. I colori del difensore e della linea dell'aggro restano come scelti."
