L["Your best food and drink, with how many you carry."] = "Il tuo miglior cibo e bevanda, con quanti ne porti."
L["Your best gear for every slot, where it drops, and where to go next."] = "Il tuo miglior equipaggiamento per ogni spazio, dove si ottiene e dove andare dopo."
