L["Your BiS only"] = "Solo il tuo BiS"
L["Your BiS you do not have yet: where to go next."] = "I BiS che non hai ancora: dove andare dopo."
L["Your BiS's star on a slot, and Forever's mark on what is new in Forever."] = "La stella del tuo BiS su uno spazio, e il segno di Forever su ciò che è nuovo in Forever."
L["Your BiS, your second pick, and so on."] = "Il tuo BiS, la tua seconda scelta, e così via."
L["Your buttons and a clock along the top."] = "I tuoi pulsanti e un orologio lungo il bordo superiore."
L["Your buttons on either side of an optional clock, with FPS and latency underneath."] = "I tuoi pulsanti ai lati di un orologio facoltativo, con FPS e latenza sotto."
L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "I tuoi pulsanti ai lati di un orologio facoltativo, con FPS e latenza sotto. Disponi i pulsanti nell'anteprima: trascinane uno per spostarlo, la sua x lo rimuove, il + di un lato ne aggiunge uno. Sposta la barra nell'Editor HUD."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "I bonus e il tempo rimasto del tuo accampamento sullo schermo, e un promemoria quando Camp Benefits scade."
L["Your camp's bonuses by the icon, always or while you hover it."] = "I bonus del tuo accampamento accanto all'icona, sempre o quando ci passi sopra."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "Il tuo massimo è %d.\nPrima fai la missione %s%s|r (%sabilità %d):"
L["Your cap is %d.\nFirst read %s (needs skill %d):"] = "Il tuo massimo è %d.\nPrima leggi %s (richiede abilità %d):"
L["Your cap is %d.\nFirst train %s (%s, needs skill %d):"] = "Il tuo massimo è %d.\nPrima apprendi %s (%s, richiede abilità %d):"
L["Your cast ends before the swing comes due."] = "Il tuo lancio finisce prima del colpo."
L["Your cast will still be going as the swing comes due."] = "Il tuo lancio sarà ancora in corso al momento del colpo."
L["Your casts and channels swept around the ring too."] = "Anche i tuoi lanci e incanalamenti scorrono attorno all'anello."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Il tuo pannello del personaggio (C) nello stile della lista BiS: ogni spazio con i suoi segni, le tue statistiche per la tua specializzazione e il tuo Naowh Score sotto il livello. Il gioco mantiene il pannello e tutto ciò che fa. Con EllesmereUI, attivare questa opzione disattiva il suo pannello del personaggio, e disattivarla lo riattiva, dopo un reload."
L["Your Characters"] = "I tuoi personaggi"
L["Your characters at level %d"] = "I tuoi personaggi al livello %d"
L["Your characters at level %d (%s)"] = "I tuoi personaggi al livello %d (%s)"
L["Your characters on this realm and faction, remembered across your account: what they hold on item tooltips, and help at the mailbox."] = "I tuoi personaggi su questo reame e fazione, ricordati in tutto l'account: cosa possiedono nei tooltip degli oggetti, e aiuto alla cassetta postale."
L["Your Chat"] = "La tua chat"
L["Your chat only"] = "Solo la tua chat"
L["Your class macros and the Macros settings"] = "Le tue macro di classe e le impostazioni di Macro"
L["Your class macros and the Macros settings."] = "Le tue macro di classe e le impostazioni di Macro."
L["Your class's BiS lists"] = "Le liste BiS della tua classe"
L["Your class's trainers only."] = "Solo gli istruttori della tua classe."
L["Your code to claim your badge, the same as /nf badges id."] = "Il tuo codice per richiedere il distintivo, lo stesso di /nf badges id."
L["Your Color"] = "Il tuo colore"
L["Your consumables on a bar you can click."] = "I tuoi consumabili su una barra cliccabile."
L["Your Corpse"] = "Il tuo cadavere"
L["your debuffs"] = "le tue penalità"
L["Your equipment sets, the same ones the character sheet keeps."] = "I tuoi set di equipaggiamento, gli stessi della scheda del personaggio."
L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "La tua esperienza all'ora su una piccola scheda, con tempo al livello, tempo di gioco, durata della sessione e tempi dei livelli recenti. Nascosta al livello massimo. Passaci sopra per Avvia, Pausa e Azzera (anche /naowh xp start, pause o reset). Spostala nell'Editor HUD."
L["Your experience. Its left end is a darker shade."] = "La tua esperienza. La sua estremità sinistra è di una tonalità più scura."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Il tuo volo su una scheda: tempo rimasto, le tappe su un percorso e la prossima tappa."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "I lanci del tuo focus su una barra propria, colorata in base a se la tua interruzione è pronta, con una tacca dove torna disponibile e uno scudo sui lanci che non puoi interrompere. La tua interruzione è la prima che conosci tra Pugno, Colpo di Scudo, Calcio, Controincantesimo, Scossa di Terra, Silenzio e Carica Ferina. Spostala nell'Editor HUD."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "Il nome del tuo focus, colorato per classe, con la sua icona di classe sopra il pannello."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Il tuo focus, impostato con NF Focus: i suoi timer continuano a contare mentre combatti qualcun altro."
L["Your game macros, not the Smart Macros, as one string to share."] = "Le tue macro di gioco, non le macro intelligenti, in un'unica stringa da condividere."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Il tuo tempo di recupero globale che scorre attorno all'anello, e un anello di pronto quando finisce."
L["YOUR GOLD"] = "IL TUO ORO"
L["Your group in range: who is missing a blessing, who is running out, and who only needs their own."] = "Il tuo gruppo in portata: a chi manca una benedizione, a chi sta finendo, e chi ha bisogno solo della propria."
L["Your group on a boss you are tanking."] = "Il tuo gruppo su un boss che stai difendendo."
L["Your group's bars, with sample members."] = "Le barre del tuo gruppo, con membri di esempio."
L["Your group's gear, talents and Naowh Score."] = "Equipaggiamento, talenti e Naowh Score del tuo gruppo."
L["Your group's healers and their mana, lowest first."] = "I guaritori del tuo gruppo e il loro mana, dal più basso."
L["Your group's Naowh Score, gear, talents and stats."] = "Naowh Score, equipaggiamento, talenti e statistiche del tuo gruppo."
L["Your group's threat on your target."] = "La minaccia del tuo gruppo sul tuo bersaglio."
L["Your healers' mana, with sample healers."] = "Il mana dei tuoi guaritori, con guaritori di esempio."
L["Your health under the threshold, with a healing item in your bags."] = "La tua salute sotto la soglia, con un oggetto curativo nelle borse."
L["Your health under the threshold, with nothing to drink or eat."] = "La tua salute sotto la soglia, senza niente da bere o mangiare."
L["Your keys stay as they are."] = "I tuoi tasti restano come sono."
L["Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour."] = "Il tuo livello, l'esperienza e la percentuale su una barra, con i PE delle missioni completate e l'esperienza da riposo disegnati oltre il riempimento. Sostituisce la barra dell'esperienza di Blizzard mentre è attiva. Spostala nell'Editor HUD. Ctrl + clic destro sulla barra per azzerare il tempo della sessione e i PE/ora."
L["Your List"] = "La tua lista"
L["Your list's marks on items out in the game."] = "I segni della tua lista sugli oggetti nel gioco."
L["Your list's rank on the items in it."] = "La posizione nella tua lista sui suoi oggetti."
L["Your list: %s%s"] = "La tua lista: %s%s"
L["Your macros"] = "Le tue macro"
L["Your macros are never changed or copied twice."] = "Le tue macro non vengono mai modificate o copiate due volte."
L["Your macros, checked and kept current."] = "Le tue macro, controllate e aggiornate."
L["Your Materials"] = "I tuoi materiali"
L["Your materials"] = "I tuoi materiali"
L["Your Naowh Score, big under your level: hover it for your score with your BiS and the best in the game, click it for the BiS List."] = "Il tuo Naowh Score, grande sotto il livello: passaci sopra per il punteggio con il tuo BiS e il migliore del gioco, cliccalo per la lista BiS."
L["Your note on %s"] = "La tua nota su %s"
L["Your Own"] = "Personale"
L["Your own bar among the group's."] = "La tua barra tra quelle del gruppo."
