L["Your rank's color (BiS orange)"] = "Colore del tuo grado (BiS arancione)"
L["Your recent casts as icons scrolling away from a point, with a bar underneath while you were casting or on the global cooldown. Gaps in the bar are time spent doing nothing. Move it in the HUD Editor."] = "I tuoi lanci recenti come icone che scorrono via da un punto, con una barra sotto mentre lanciavi o eri nel tempo di recupero globale. I vuoti nella barra sono tempo passato senza fare nulla. Spostalo nell'Editor HUD."
