L["Your settings stay as they are."] = "Le tue impostazioni restano come sono."
L["Your settings stay."] = "Le tue impostazioni restano."
L["Your setup is ready."] = "La tua configurazione è pronta."
L["Your setup is ready. Reload now to finish?"] = "La tua configurazione è pronta. Ricaricare ora per finire?"
