L["Your target's short buffs, the crowd control on them and the debuffs you pick, as large icons that keep working in combat."] = "I benefici brevi del tuo bersaglio, gli effetti di controllo su di lui e le penalità che scegli, come grandi icone che continuano a funzionare in combattimento."
