L["Your two trinket slots, movable: left-click to use one, right-click to equip a trinket from your bags outside combat. Move it in the HUD Editor."] = "I tuoi due spazi dei monili, spostabili: clic sinistro per usarne uno, clic destro per equipaggiare un monile dalle borse fuori dal combattimento. Spostali nell'Editor HUD."
